static inline void fasim_put_varint(std::string &out, uint64_t value)
{
	while (value >= 0x80)
	{
		out.push_back(static_cast<char>((value & 0x7f) | 0x80));
		value >>= 7;
	}
	out.push_back(static_cast<char>(value));
}

static inline uint64_t fasim_zigzag_i64(int64_t value)
{
	return value >= 0 ?
		static_cast<uint64_t>(value) << 1 :
		(static_cast<uint64_t>(-value) << 1) - 1;
}

static inline void fasim_put_delta_varint(std::string &out,
                                          int64_t value,
                                          int64_t &previous)
{
	const int64_t delta = value - previous;
	fasim_put_varint(out, fasim_zigzag_i64(delta));
	previous = value;
}

static inline void fasim_put_bytes(std::string &out, const std::string &value)
{
	fasim_put_varint(out, static_cast<uint64_t>(value.size()));
	out.append(value);
}

static inline std::string fasim_encode_varints(const std::vector<uint64_t> &values)
{
	std::string out;
	for (size_t i = 0; i < values.size(); ++i)
	{
		fasim_put_varint(out, values[i]);
	}
	return out;
}

static inline std::string fasim_encode_delta_varints(const std::vector<int64_t> &values)
{
	std::string out;
	int64_t previous = 0;
	for (size_t i = 0; i < values.size(); ++i)
	{
		fasim_put_delta_varint(out, values[i], previous);
	}
	return out;
}

static inline std::string fasim_encode_bytes_column(const std::vector<std::string> &values)
{
	std::string out;
	for (size_t i = 0; i < values.size(); ++i)
	{
		fasim_put_bytes(out, values[i]);
	}
	return out;
}

static inline std::string fasim_encode_dictionary_column(const std::vector<std::string> &values)
{
	std::set<std::string> unique(values.begin(), values.end());
	std::vector<std::string> dictionary(unique.begin(), unique.end());
	std::map<std::string, uint64_t> index;
	for (size_t i = 0; i < dictionary.size(); ++i)
	{
		index[dictionary[i]] = static_cast<uint64_t>(i);
	}
	std::string out;
	fasim_put_varint(out, static_cast<uint64_t>(dictionary.size()));
	for (size_t i = 0; i < dictionary.size(); ++i)
	{
		fasim_put_bytes(out, dictionary[i]);
	}
	for (size_t i = 0; i < values.size(); ++i)
	{
		fasim_put_varint(out, index[values[i]]);
	}
	return out;
}

struct FasimCigarOp
{
	FasimCigarOp(uint64_t lenValue, char opValue) :
		len(lenValue),
		op(opValue)
	{
	}
	uint64_t len;
	char op;
};

static inline std::vector<FasimCigarOp> fasim_parse_cigar_probe(const std::string &cigar)
{
	std::vector<FasimCigarOp> ops;
	uint64_t len = 0;
	bool haveLen = false;
	for (size_t i = 0; i < cigar.size(); ++i)
	{
		const char ch = cigar[i];
		if (ch >= '0' && ch <= '9')
		{
			len = len * 10 + static_cast<uint64_t>(ch - '0');
			haveLen = true;
			continue;
		}
		if (!haveLen || len == 0)
		{
			cerr << "compact archive probe bad CIGAR: " << cigar << endl;
			abort();
		}
		ops.push_back(FasimCigarOp(len, ch));
		len = 0;
		haveLen = false;
	}
	if (haveLen)
	{
		cerr << "compact archive probe bad trailing CIGAR length: " << cigar << endl;
		abort();
	}
	return ops;
}

static inline uint64_t fasim_cigar_query_len(const std::vector<FasimCigarOp> &cigar)
{
	uint64_t len = 0;
	for (size_t i = 0; i < cigar.size(); ++i)
	{
		const char op = cigar[i].op;
		if (op == 'M' || op == '=' || op == 'X' || op == 'I' || op == 'S')
		{
			len += cigar[i].len;
		}
	}
	return len;
}

static inline uint64_t fasim_cigar_target_len(const std::vector<FasimCigarOp> &cigar)
{
	uint64_t len = 0;
	for (size_t i = 0; i < cigar.size(); ++i)
	{
		const char op = cigar[i].op;
		if (op == 'M' || op == '=' || op == 'X' || op == 'D')
		{
			len += cigar[i].len;
		}
	}
	return len;
}

static inline std::string fasim_cigar_gap_mask(const std::vector<FasimCigarOp> &cigar,
                                               bool queryMask)
{
	uint64_t alignedLen = 0;
	for (size_t i = 0; i < cigar.size(); ++i)
	{
		const char op = cigar[i].op;
		if (op == 'M' || op == '=' || op == 'X' || op == 'I' || op == 'D')
		{
			alignedLen += cigar[i].len;
		}
	}
	std::string mask(static_cast<size_t>((alignedLen + 7) / 8), '\0');
	uint64_t pos = 0;
	for (size_t i = 0; i < cigar.size(); ++i)
	{
		const char op = cigar[i].op;
		const uint64_t len = cigar[i].len;
		if (op != 'M' && op != '=' && op != 'X' && op != 'I' && op != 'D')
		{
			continue;
		}
		const bool gap = queryMask ? op == 'D' : op == 'I';
		if (gap)
		{
			for (uint32_t j = 0; j < len; ++j)
			{
				const uint64_t bit = pos + j;
				mask[static_cast<size_t>(bit / 8)] =
					static_cast<char>(
						static_cast<unsigned char>(
							mask[static_cast<size_t>(bit / 8)]) |
						static_cast<unsigned char>(1u << (bit % 8)));
			}
		}
		pos += len;
	}
	return mask;
}

static inline uint64_t fasim_cigar_aligned_len(const std::vector<FasimCigarOp> &cigar)
{
	uint64_t len = 0;
	for (size_t i = 0; i < cigar.size(); ++i)
	{
		const char op = cigar[i].op;
		if (op == 'M' || op == '=' || op == 'X' || op == 'I' || op == 'D')
		{
			len += cigar[i].len;
		}
	}
	return len;
}

static inline std::vector<FasimCigarOp> fasim_cigar_ops_from_alignment(
	const std::vector<uint32_t> &cigar)
{
	std::vector<FasimCigarOp> ops;
	ops.reserve(cigar.size());
	for (size_t i = 0; i < cigar.size(); ++i)
	{
		ops.push_back(FasimCigarOp(cigar_int_to_len(cigar[i]),
		                           cigar_int_to_op(cigar[i])));
	}
	return ops;
}

static inline int fasim_compact_strand_code(int reverse, int strand)
{
	const std::string value = getStrand(reverse, strand);
	if (value == "ParaPlus")
	{
		return 0;
	}
	if (value == "ParaMinus")
	{
		return 1;
	}
	if (value == "AntiPlus")
	{
		return 2;
	}
	if (value == "AntiMinus")
	{
		return 3;
	}
	return -1;
}

struct FasimCompactArchiveProbeWriter
{
	FasimCompactArchiveProbeWriter() :
		opened(false),
		previousQueryStart(0),
		previousSeqStart(0),
		previousScore(0)
	{
	}

	void open(const std::string &path)
	{
		file.open(path.c_str(), ios::binary | ios::trunc);
		if (!file.is_open())
		{
			cerr << "failed to open compact archive probe: " << path << endl;
			abort();
		}
		static const char magic[] = "FATFOD1";
		file.write(magic, 8);
		const uint32_t version = 1;
		file.write(reinterpret_cast<const char*>(&version), sizeof(version));
		opened = true;
	}

	void write_row(const triplex &atr,
	               int motif,
	               int middle,
	               int center)
	{
		if (!opened)
		{
			return;
		}
		const int strandCode =
			fasim_compact_strand_code(atr.reverse, atr.strand);
		if (strandCode < 0 ||
		    atr.starj >= atr.endj ||
		    !atr.chr.empty() ||
		    atr.genomestart != atr.starj ||
		    atr.genomeend != atr.endj ||
		    motif != 0 ||
		    middle != center)
		{
			cerr << "compact archive probe unsupported row shape" << endl;
			abort();
		}
		if (atr.cigar_probe.empty())
		{
			cerr << "compact archive probe missing CIGAR" << endl;
			abort();
		}
		const std::vector<FasimCigarOp> cigar =
			fasim_parse_cigar_probe(atr.cigar_probe);
		const uint64_t alignedLen = fasim_cigar_aligned_len(cigar);
		const uint64_t queryLen = fasim_cigar_query_len(cigar);
		const uint64_t targetLen = fasim_cigar_target_len(cigar);
		if (queryLen == 0 || targetLen == 0 ||
		    atr.endi != atr.stari + static_cast<int>(queryLen) - 1 ||
		    atr.endj != atr.starj + static_cast<int>(targetLen) - 1 ||
		    atr.nt != static_cast<int>(alignedLen))
		{
			cerr << "compact archive probe unsupported CIGAR-derived row"
			     << endl;
			abort();
		}
		std::string row;
		fasim_put_delta_varint(row, atr.stari, previousQueryStart);
		fasim_put_delta_varint(row, atr.starj, previousSeqStart);
		fasim_put_delta_varint(row, static_cast<int64_t>(atr.score), previousScore);
		fasim_put_varint(row, alignedLen);
		fasim_put_varint(row, queryLen);
		fasim_put_varint(row, targetLen);
		fasim_put_varint(row, static_cast<uint64_t>(atr.rule));
		fasim_put_varint(row, static_cast<uint64_t>(atr.nt));
		const uint64_t flags = static_cast<uint64_t>(strandCode << 1);
		fasim_put_varint(row, flags);
		{
			std::ostringstream value;
			value << atr.tri_score;
			fasim_put_bytes(row, value.str());
		}
		{
			std::ostringstream value;
			value << atr.identity;
			fasim_put_bytes(row, value.str());
		}
		fasim_put_bytes(row, fasim_cigar_gap_mask(cigar, true));
		fasim_put_bytes(row, fasim_cigar_gap_mask(cigar, false));
		std::string prefix;
		fasim_put_varint(prefix, static_cast<uint64_t>(row.size()));
		file.write(prefix.data(), static_cast<std::streamsize>(prefix.size()));
		file.write(row.data(), static_cast<std::streamsize>(row.size()));
	}

	void close()
	{
		if (opened)
		{
			file.close();
			opened = false;
		}
	}

	bool opened;
	ofstream file;
	int64_t previousQueryStart;
	int64_t previousSeqStart;
	int64_t previousScore;
};

struct FasimColumnArchiveProbeWriter
{
	FasimColumnArchiveProbeWriter() :
		opened(false),
		blockRows(65536),
		bytesWritten(0),
		blocksWritten(0)
	{
	}

	void open(const std::string &path)
	{
		file.open(path.c_str(), ios::binary | ios::trunc);
		if (!file.is_open())
		{
			cerr << "failed to open column archive probe: " << path << endl;
			abort();
		}
			static const char magic[] = "FATFOC1";
			file.write(magic, 8);
			const uint32_t version = 2;
			const uint32_t blockRowsOut = static_cast<uint32_t>(blockRows);
			file.write(reinterpret_cast<const char*>(&version), sizeof(version));
			file.write(reinterpret_cast<const char*>(&blockRowsOut), sizeof(blockRowsOut));
			bytesWritten = 8 + sizeof(version) + sizeof(blockRowsOut);
			blocksWritten = 0;
			opened = true;
		}

	void write_row(const triplex &atr,
	               int motif,
	               int middle,
	               int center)
	{
		if (!opened)
		{
			return;
		}
		const int strandCode =
			fasim_compact_strand_code(atr.reverse, atr.strand);
		if (strandCode < 0 ||
		    atr.starj >= atr.endj ||
		    !atr.chr.empty() ||
		    atr.genomestart != atr.starj ||
		    atr.genomeend != atr.endj ||
		    motif != 0 ||
		    middle != center)
		{
			cerr << "column archive probe unsupported row shape" << endl;
			abort();
		}
		std::vector<FasimCigarOp> cigar;
		if (!atr.typed_cigar.empty())
		{
			cigar = fasim_cigar_ops_from_alignment(atr.typed_cigar);
		}
		else if (!atr.cigar_probe.empty())
		{
			cigar = fasim_parse_cigar_probe(atr.cigar_probe);
		}
		else
		{
			cerr << "column archive probe missing CIGAR" << endl;
			abort();
		}
		const uint64_t alignedLen = fasim_cigar_aligned_len(cigar);
		const uint64_t queryLen = fasim_cigar_query_len(cigar);
		const uint64_t targetLen = fasim_cigar_target_len(cigar);
		if (queryLen == 0 || targetLen == 0 ||
		    atr.endi != atr.stari + static_cast<int>(queryLen) - 1 ||
		    atr.endj != atr.starj + static_cast<int>(targetLen) - 1 ||
		    atr.nt != static_cast<int>(alignedLen))
		{
			cerr << "column archive probe unsupported CIGAR-derived row"
			     << endl;
			abort();
		}
		qStart.push_back(atr.stari);
		seqStart.push_back(atr.starj);
		score.push_back(static_cast<int64_t>(atr.score));
		alignLen.push_back(static_cast<int64_t>(alignedLen));
		qLen.push_back(queryLen);
		targetLenVec.push_back(targetLen);
		rule.push_back(static_cast<uint64_t>(atr.rule));
		nt.push_back(static_cast<uint64_t>(atr.nt));
		flags.push_back(static_cast<unsigned char>(strandCode << 1));
		{
			std::ostringstream value;
			value << atr.tri_score;
			stability.push_back(value.str());
		}
		{
			std::ostringstream value;
			value << atr.identity;
			identity.push_back(value.str());
		}
		tfoMasks.push_back(fasim_cigar_gap_mask(cigar, true));
		ttsMasks.push_back(fasim_cigar_gap_mask(cigar, false));
		if (qStart.size() >= blockRows)
		{
			flush();
		}
	}

	void write_direct_row(int stari,
	                      int endi,
	                      int starj,
	                      int endj,
	                      int reverse,
	                      int strand,
	                      int ruleValue,
	                      int ntValue,
	                      int scoreValue,
	                      float triScoreValue,
	                      float identityValue,
	                      const std::vector<FasimCigarOp> &cigar)
	{
		if (!opened)
		{
			return;
		}
		const int strandCode = fasim_compact_strand_code(reverse, strand);
		if (strandCode < 0 || starj >= endj)
		{
			cerr << "column archive probe unsupported direct row shape" << endl;
			abort();
		}
		const uint64_t alignedLen = fasim_cigar_aligned_len(cigar);
		const uint64_t queryLen = fasim_cigar_query_len(cigar);
		const uint64_t targetLen = fasim_cigar_target_len(cigar);
		if (queryLen == 0 || targetLen == 0 ||
		    endi != stari + static_cast<int>(queryLen) - 1 ||
		    endj != starj + static_cast<int>(targetLen) - 1 ||
		    ntValue != static_cast<int>(alignedLen))
		{
			cerr << "column archive probe unsupported direct CIGAR-derived row"
			     << endl;
			abort();
		}
		qStart.push_back(stari);
		seqStart.push_back(starj);
		score.push_back(static_cast<int64_t>(scoreValue));
		alignLen.push_back(static_cast<int64_t>(alignedLen));
		qLen.push_back(queryLen);
		targetLenVec.push_back(targetLen);
		rule.push_back(static_cast<uint64_t>(ruleValue));
		nt.push_back(static_cast<uint64_t>(ntValue));
		flags.push_back(static_cast<unsigned char>(strandCode << 1));
		{
			std::ostringstream value;
			value << triScoreValue;
			stability.push_back(value.str());
		}
		{
			std::ostringstream value;
			value << identityValue;
			identity.push_back(value.str());
		}
		tfoMasks.push_back(fasim_cigar_gap_mask(cigar, true));
		ttsMasks.push_back(fasim_cigar_gap_mask(cigar, false));
		if (qStart.size() >= blockRows)
		{
			flush();
		}
	}

	void write_converted_row(const FasimConvertedTriplexRecord &record)
	{
		if (!opened)
		{
			return;
		}
		const int strandCode =
			fasim_compact_strand_code(record.reverse, record.strand);
		if (strandCode < 0 || record.starj >= record.endj ||
		    record.motif != 0 ||
		    record.middle != record.center)
		{
			cerr << "column archive probe unsupported converted row shape"
			     << endl;
			abort();
		}
		std::vector<FasimCigarOp> cigar;
		if (!record.typed_cigar.empty())
		{
			cigar = fasim_cigar_ops_from_alignment(record.typed_cigar);
		}
		else if (!record.cigar_probe.empty())
		{
			cigar = fasim_parse_cigar_probe(record.cigar_probe);
		}
		else
		{
			cerr << "column archive probe missing converted row CIGAR"
			     << endl;
			abort();
		}
		const uint64_t alignedLen = fasim_cigar_aligned_len(cigar);
		const uint64_t queryLen = fasim_cigar_query_len(cigar);
		const uint64_t targetLen = fasim_cigar_target_len(cigar);
		if (queryLen == 0 || targetLen == 0 ||
		    record.endi != record.stari + static_cast<int>(queryLen) - 1 ||
		    record.endj != record.starj + static_cast<int>(targetLen) - 1 ||
		    record.nt != static_cast<int>(alignedLen))
		{
			cerr << "column archive probe unsupported converted CIGAR-derived row"
			     << endl;
			abort();
		}
		qStart.push_back(record.stari);
		seqStart.push_back(record.starj);
		score.push_back(static_cast<int64_t>(record.score));
		alignLen.push_back(static_cast<int64_t>(alignedLen));
		qLen.push_back(queryLen);
		targetLenVec.push_back(targetLen);
		rule.push_back(static_cast<uint64_t>(record.rule));
		nt.push_back(static_cast<uint64_t>(record.nt));
		flags.push_back(static_cast<unsigned char>(strandCode << 1));
		{
			std::ostringstream value;
			value << record.tri_score;
			stability.push_back(value.str());
		}
		{
			std::ostringstream value;
			value << record.identity;
			identity.push_back(value.str());
		}
		tfoMasks.push_back(record.query_gap_mask.empty() ?
		                   fasim_cigar_gap_mask(cigar, true) :
		                   record.query_gap_mask);
		ttsMasks.push_back(record.target_gap_mask.empty() ?
		                   fasim_cigar_gap_mask(cigar, false) :
		                   record.target_gap_mask);
		if (qStart.size() >= blockRows)
		{
			flush();
		}
	}

	void close()
	{
		if (!opened)
		{
			return;
		}
		flush();
			const uint32_t zero = 0;
			file.write(reinterpret_cast<const char*>(&zero), sizeof(zero));
			bytesWritten += sizeof(zero);
			file.close();
			opened = false;
		}

		uint64_t bytes_written() const
		{
			return bytesWritten;
		}

		uint64_t blocks_written() const
		{
			return blocksWritten;
		}

	void flush()
	{
		if (qStart.empty())
		{
			return;
		}
		std::vector<std::string> payloads;
		payloads.push_back(fasim_encode_delta_varints(qStart));
		payloads.push_back(fasim_encode_delta_varints(seqStart));
		payloads.push_back(fasim_encode_delta_varints(score));
		payloads.push_back(fasim_encode_delta_varints(alignLen));
		payloads.push_back(fasim_encode_varints(qLen));
		payloads.push_back(fasim_encode_varints(targetLenVec));
		payloads.push_back(fasim_encode_varints(rule));
		payloads.push_back(fasim_encode_varints(nt));
		payloads.push_back(std::string(reinterpret_cast<const char*>(&flags[0]),
		                               flags.size()));
		payloads.push_back(fasim_encode_dictionary_column(stability));
		payloads.push_back(fasim_encode_dictionary_column(identity));
		payloads.push_back(fasim_encode_bytes_column(tfoMasks));
		payloads.push_back(fasim_encode_bytes_column(ttsMasks));

		std::string block;
		const uint32_t rowCount = static_cast<uint32_t>(qStart.size());
		const uint32_t payloadCount = static_cast<uint32_t>(payloads.size());
		block.append(reinterpret_cast<const char*>(&rowCount), sizeof(rowCount));
		block.append(reinterpret_cast<const char*>(&payloadCount), sizeof(payloadCount));
		for (size_t i = 0; i < payloads.size(); ++i)
		{
			const uint32_t size = static_cast<uint32_t>(payloads[i].size());
			block.append(reinterpret_cast<const char*>(&size), sizeof(size));
		}
		for (size_t i = 0; i < payloads.size(); ++i)
		{
			block.append(payloads[i]);
		}
			const uint32_t blockSize = static_cast<uint32_t>(block.size());
			file.write(reinterpret_cast<const char*>(&blockSize), sizeof(blockSize));
			file.write(block.data(), static_cast<std::streamsize>(block.size()));
			bytesWritten += sizeof(blockSize) + static_cast<uint64_t>(block.size());
			++blocksWritten;
			qStart.clear();
		seqStart.clear();
		score.clear();
		alignLen.clear();
		qLen.clear();
		targetLenVec.clear();
		rule.clear();
		nt.clear();
		flags.clear();
		stability.clear();
		identity.clear();
		tfoMasks.clear();
		ttsMasks.clear();
	}

	bool opened;
		ofstream file;
		size_t blockRows;
		uint64_t bytesWritten;
		uint64_t blocksWritten;
		std::vector<int64_t> qStart;
	std::vector<int64_t> seqStart;
	std::vector<int64_t> score;
	std::vector<int64_t> alignLen;
	std::vector<uint64_t> qLen;
	std::vector<uint64_t> targetLenVec;
	std::vector<uint64_t> rule;
	std::vector<uint64_t> nt;
	std::vector<unsigned char> flags;
	std::vector<std::string> stability;
	std::vector<std::string> identity;
	std::vector<std::string> tfoMasks;
	std::vector<std::string> ttsMasks;
};

struct FasimLiteRow
{
	std::string text;
	std::string key;
	double score;
	double nt;
	double identity;
	double stability;
	uint64_t scoreinfo_rank;
};

