struct FasimGasal2PretracebackPruningEligibilityRuntime
{
	FasimGasal2PretracebackPruningEligibilityRuntime() :
		active(false),
		limit(0),
		export_rows(0),
		export_attempts(0),
		next_attempt_id(0),
		path(""),
		mutex(),
		output(),
		stats()
	{
	}

	void open()
	{
		active = fasim_gasal2_pretraceback_pruning_eligibility_runtime();
		stats.requested = active;
		stats.active = active;
		if (!active)
		{
			return;
		}
		limit = fasim_env_uint64_or_default(
			"FASIM_GASAL2_PRETRACEBACK_PRUNING_ELIGIBILITY_EXPORT_LIMIT",
			1000ULL);
		path =
			fasim_gasal2_pretraceback_pruning_eligibility_export_path_runtime();
		if (path.empty())
		{
			return;
		}
		output.open(path.c_str());
		if (!output)
		{
			return;
		}
		output
			<< "attempt_id\tflush_id\ttask_id\tscoreinfo_index\t"
			<< "prealign_score\tquery_len\ttarget_size\ttarget_start\t"
			<< "cutlength\trequest_key_hash\tdescriptor_key_hash\t"
			<< "final_row_hash\trepresentative_attempt_id\t"
			<< "representative_flush_id\trepresentative_request_key_hash\t"
			<< "representative_descriptor_key_hash\tsame_flush\t"
			<< "cross_flush\tscore\tquery_begin\tquery_end\tref_begin\t"
			<< "ref_end\toutput_global_start\toutput_global_end\tnt\t"
			<< "identity\tstability\tcigar_hash\tfinal_rejection_bucket\t"
			<< "eligibility_bucket\tpre_traceback_decidable\t"
			<< "post_traceback_only\ttop5_only_safe_candidate\t"
			<< "full_output_safe_candidate\tnotes\n";
	}

	uint64_t next_attempt()
	{
		std::lock_guard<std::mutex> lock(mutex);
		return ++next_attempt_id;
	}

	void record(const FasimGasal2PretracebackPruningEligibilityAttempt &attempt)
	{
		if (!active)
		{
			return;
		}
		std::lock_guard<std::mutex> lock(mutex);
		++stats.attempts;
		if (attempt.final_rejection_bucket == "retained_emitted")
		{
			++stats.retained_final_rows;
			++export_attempts;
			if (!output || export_rows >= limit)
			{
				return;
			}
		}
		else
		{
			++stats.removed_attempts;
			if (attempt.representative_attempt_id != 0)
			{
				++stats.mapped_removed_attempts;
			}
			else
			{
				++stats.unmapped_removed_attempts;
			}

			if (attempt.eligibility_bucket == "exact_request_duplicate")
			{
				++stats.exact_request_duplicate;
			}
			else if (attempt.eligibility_bucket ==
			         "exact_descriptor_duplicate")
			{
				++stats.exact_descriptor_duplicate;
			}
			else if (attempt.eligibility_bucket ==
			         "same_final_row_different_descriptor")
			{
				++stats.same_final_row_different_descriptor;
			}
			else if (attempt.eligibility_bucket ==
			         "cross_flush_exact_duplicate")
			{
				++stats.cross_flush_exact_duplicate;
			}
			else if (attempt.eligibility_bucket ==
			         "cigar_dependent_duplicate")
			{
				++stats.cigar_dependent_duplicate;
			}
			else if (attempt.eligibility_bucket ==
			         "representative_selection_dependent")
			{
				++stats.representative_selection_dependent;
			}
			else if (attempt.eligibility_bucket ==
			         "sort_or_dominance_removed")
			{
				++stats.sort_or_dominance_removed;
			}
			else if (attempt.eligibility_bucket ==
			         "pretraceback_span_provable")
			{
				++stats.pretraceback_span_provable;
			}
			else if (attempt.eligibility_bucket ==
			         "reverse_start_dependent_span")
			{
				++stats.reverse_start_dependent_span;
			}
			else if (attempt.eligibility_bucket == "cigar_dependent_span")
			{
				++stats.cigar_dependent_span;
			}
			else if (attempt.eligibility_bucket == "unknown")
			{
				++stats.unknown;
			}
			else
			{
				++stats.unknown;
			}

			++export_attempts;
			if (!output || export_rows >= limit)
			{
				return;
			}
		}
		output
			<< attempt.attempt_id << "\t"
			<< attempt.flush_id << "\t"
			<< attempt.task_id << "\t"
			<< attempt.scoreinfo_index << "\t"
			<< attempt.prealign_score << "\t"
			<< attempt.query_len << "\t"
			<< attempt.target_size << "\t"
			<< attempt.target_start << "\t"
			<< attempt.cutlength << "\t"
			<< attempt.request_key_hash << "\t"
			<< attempt.descriptor_key_hash << "\t"
			<< attempt.final_row_hash << "\t"
			<< attempt.representative_attempt_id << "\t"
			<< attempt.representative_flush_id << "\t"
			<< attempt.representative_request_key_hash << "\t"
			<< attempt.representative_descriptor_key_hash << "\t"
			<< (attempt.same_flush ? 1 : 0) << "\t"
			<< (attempt.cross_flush ? 1 : 0) << "\t"
			<< attempt.score << "\t"
			<< attempt.query_begin << "\t"
			<< attempt.query_end << "\t"
			<< attempt.ref_begin << "\t"
			<< attempt.ref_end << "\t"
			<< attempt.output_global_start << "\t"
			<< attempt.output_global_end << "\t"
			<< attempt.nt << "\t"
			<< attempt.identity << "\t"
			<< attempt.stability << "\t"
			<< attempt.cigar_hash << "\t"
			<< attempt.final_rejection_bucket << "\t"
			<< attempt.eligibility_bucket << "\t"
			<< (attempt.pre_traceback_decidable ? 1 : 0) << "\t"
			<< (attempt.post_traceback_only ? 1 : 0) << "\t"
			<< (attempt.top5_only_safe_candidate ? 1 : 0) << "\t"
			<< (attempt.full_output_safe_candidate ? 1 : 0) << "\t"
			<< attempt.notes << "\n";
		++export_rows;
	}

	FasimGasal2PretracebackPruningEligibilityStats snapshot() const
	{
		std::lock_guard<std::mutex> lock(mutex);
		FasimGasal2PretracebackPruningEligibilityStats out = stats;
		out.export_path = path;
		out.export_rows = export_rows;
		out.export_truncated = export_attempts > export_rows;
		return out;
	}

	bool active;
	uint64_t limit;
	uint64_t export_rows;
	uint64_t export_attempts;
	uint64_t next_attempt_id;
	std::string path;
	mutable std::mutex mutex;
	std::ofstream output;
	FasimGasal2PretracebackPruningEligibilityStats stats;
};

static inline uint64_t fasim_hash_int64(uint64_t digest, int64_t value)
{
	for (int i = 0; i < 8; ++i)
	{
		const unsigned char byte =
			static_cast<unsigned char>((static_cast<uint64_t>(value) >>
			                            (i * 8)) & 0xffU);
		digest ^= byte;
		digest *= 1099511628211ULL;
	}
	return digest;
}

static inline uint64_t fasim_hash_string_field(uint64_t digest,
                                               const std::string &value)
{
	digest = fasim_hash_int64(digest, static_cast<int64_t>(value.size()));
	return fasim_fnv1a_update(digest, value);
}

static inline std::string fasim_hash_selected_request(
	const FasimGasal2SelectedAlignment &selectedAlignment,
	uint64_t taskId)
{
	uint64_t digest = 1469598103934665603ULL;
	digest = fasim_hash_int64(digest, static_cast<int64_t>(taskId));
	digest = fasim_hash_int64(
		digest,
		static_cast<int64_t>(selectedAlignment.scoreinfo_index));
	digest = fasim_hash_int64(digest,
	                          static_cast<int64_t>(selectedAlignment.start));
	digest = fasim_hash_int64(
		digest,
		static_cast<int64_t>(selectedAlignment.cutlength));
	digest = fasim_hash_int64(
		digest,
		static_cast<int64_t>(selectedAlignment.score_prepass_score));
	digest = fasim_hash_int64(
		digest,
		static_cast<int64_t>(selectedAlignment.score_prepass_query_end));
	digest = fasim_hash_int64(
		digest,
		static_cast<int64_t>(selectedAlignment.score_prepass_ref_end));
	return fasim_hex_u64(digest);
}

static inline std::string fasim_hash_selected_descriptor(
	const FasimGasal2SelectedAlignment &selectedAlignment,
	const StripedSmithWaterman::Alignment &alignment,
	uint64_t taskId)
{
	uint64_t digest = 1469598103934665603ULL;
	digest = fasim_hash_int64(digest, static_cast<int64_t>(taskId));
	digest = fasim_hash_int64(
		digest,
		static_cast<int64_t>(selectedAlignment.scoreinfo_index));
	digest = fasim_hash_int64(digest,
	                          static_cast<int64_t>(selectedAlignment.start));
	digest = fasim_hash_int64(
		digest,
		static_cast<int64_t>(selectedAlignment.cutlength));
	digest = fasim_hash_int64(digest,
	                          static_cast<int64_t>(alignment.sw_score));
	digest = fasim_hash_int64(digest,
	                          static_cast<int64_t>(alignment.query_begin));
	digest = fasim_hash_int64(digest,
	                          static_cast<int64_t>(alignment.query_end));
	digest = fasim_hash_int64(digest,
	                          static_cast<int64_t>(alignment.ref_begin));
	digest = fasim_hash_int64(digest,
	                          static_cast<int64_t>(alignment.ref_end));
	return fasim_hex_u64(digest);
}

static inline std::string fasim_hash_cigar(
	const std::vector<uint32_t> &cigar)
{
	uint64_t digest = 1469598103934665603ULL;
	digest = fasim_hash_int64(digest, static_cast<int64_t>(cigar.size()));
	for (size_t i = 0; i < cigar.size(); ++i)
	{
		digest = fasim_hash_int64(digest, static_cast<int64_t>(cigar[i]));
	}
	return fasim_hex_u64(digest);
}

static inline std::string fasim_hash_lite_row_key(const std::string &key)
{
	return fasim_hex_u64(fasim_hash_string_field(1469598103934665603ULL, key));
}

static inline std::string fasim_canonical_hybrid_v2_cigar(
	const std::vector<uint32_t> &cigar)
{
	if (cigar.empty())
	{
		return "*";
	}
	std::ostringstream out;
	for (size_t i = 0; i < cigar.size(); ++i)
	{
		out << cigar_int_to_len(cigar[i]) << cigar_int_to_op(cigar[i]);
	}
	return out.str();
}

static inline std::string fasim_canonical_hybrid_v2_row_text(
	const triplex &input,
	const std::string &taskChr,
	long recordStartGenome)
{
	triplex row = input;
	if (row.chr.empty())
	{
		row.chr = taskChr;
	}
	if (row.genomestart == 0)
	{
		row.genomestart = row.starj + recordStartGenome - 1;
	}
	if (row.genomeend == 0)
	{
		row.genomeend = row.endj + recordStartGenome - 1;
	}
	const int midpoint = static_cast<int>((row.stari + row.endi) / 2);
	std::ostringstream out;
	out << row.stari << "\t" << row.endi << "\t"
	    << row.starj << "\t" << row.endj << "\t"
	    << (row.starj < row.endj ? "R" : "L") << "\t"
	    << row.chr << "\t" << row.genomestart << "\t" << row.genomeend << "\t"
	    << row.tri_score << "\t" << row.identity << "\t"
	    << getStrand(row.reverse, row.strand) << "\t"
	    << row.rule << "\t" << row.score << "\t" << row.nt << "\t"
	    << 0 << "\t" << midpoint << "\t" << midpoint << "\t"
	    << row.stri_align << "\t" << row.strj_align;
	return out.str();
}

static inline std::string fasim_canonical_hybrid_v2_row_digest(
	const triplex &row,
	const std::string &taskChr,
	long recordStartGenome)
{
	const std::string text =
		fasim_canonical_hybrid_v2_row_text(row, taskChr, recordStartGenome);
	return std::string("fnv1a64:") +
	       fasim_hex_u64(fasim_fnv1a_update(1469598103934665603ULL, text));
}

struct FasimCanonicalHybridV2AttemptTelemetryRow
{
	FasimCanonicalHybridV2AttemptTelemetryRow() :
		batch_id(0), attempt_index(-1), task_id(0), scoreinfo_index(-1),
		scoreinfo_position(-1), rule(-1), strand(-1), para(-1),
		identity_round(-1), start(0), cutlength(0), prealign_threshold(0),
		gpu_score(0), gpu_query_end(-1), gpu_ref_end_global(-1), selected(false),
		selection_reason("not_evaluated"), cpu_called(false), cpu_score(0),
		cpu_query_begin(-1), cpu_query_end(-1), cpu_ref_begin_local(-1),
		cpu_ref_end_local(-1), cpu_cigar("NA"), cpu_emit_reason("not_selected"),
		converted_row_digest("NA"), final_row_digest("NA"),
		final_status("not_selected")
	{
	}

	uint64_t batch_id;
	int64_t attempt_index;
	uint64_t task_id;
	int scoreinfo_index;
	int scoreinfo_position;
	int rule;
	int strand;
	int para;
	int identity_round;
	int start;
	int cutlength;
	int prealign_threshold;
	int gpu_score;
	int gpu_query_end;
	int gpu_ref_end_global;
	bool selected;
	std::string selection_reason;
	bool cpu_called;
	int cpu_score;
	int cpu_query_begin;
	int cpu_query_end;
	int cpu_ref_begin_local;
	int cpu_ref_end_local;
	std::string cpu_cigar;
	std::string cpu_emit_reason;
	std::string converted_row_digest;
	std::string final_row_digest;
	std::string final_status;
};

struct FasimCanonicalHybridV2TelemetryExporter
{
	FasimCanonicalHybridV2TelemetryExporter() :
		requested(false), active(false), failed(false), next_batch_id(0),
		rows(0), selected_rows(0), cpu_rows(0), final_rows(0), path(""),
		failure_reason("none"), output()
	{
	}

	void open()
	{
		requested = fasim_canonical_hybrid_v2_runtime();
		if (!requested)
		{
			return;
		}
		path = fasim_canonical_hybrid_v2_telemetry_path_runtime();
		if (path.empty())
		{
			fail("telemetry_path_missing");
			return;
		}
		std::ifstream existing(path.c_str());
		if (existing.good())
		{
			fail("telemetry_path_exists");
			return;
		}
		output.open(path.c_str(), std::ios::out | std::ios::trunc);
		if (!output)
		{
			fail("telemetry_path_open_failed");
			return;
		}
		output
			<< "batch_id\tattempt_index\ttask_id\tscoreinfo_index\t"
			<< "scoreinfo_position\trule\tstrand\tpara\tidentity_round\tstart\t"
			<< "cutlength\tprealign_threshold\tgpu_score\tgpu_query_end\t"
			<< "gpu_ref_end_global\tselected\tselection_reason\tcpu_called\t"
			<< "cpu_score\tcpu_query_begin\tcpu_query_end\tcpu_ref_begin_local\t"
			<< "cpu_ref_end_local\tcpu_cigar\tcpu_emit_reason\t"
			<< "converted_row_digest\tfinal_row_digest\tfinal_status\n";
		active = true;
	}

	void fail(const std::string &reason)
	{
		failed = true;
		active = false;
		failure_reason = reason;
	}

	uint64_t begin_batch()
	{
		return next_batch_id++;
	}

	bool append(const std::vector<FasimCanonicalHybridV2AttemptTelemetryRow> &batch)
	{
		if (!active || failed)
		{
			return false;
		}
		for (size_t i = 0; i < batch.size(); ++i)
		{
			const FasimCanonicalHybridV2AttemptTelemetryRow &row = batch[i];
			output << row.batch_id << "\t" << row.attempt_index << "\t"
			       << row.task_id << "\t" << row.scoreinfo_index << "\t"
			       << row.scoreinfo_position << "\t" << row.rule << "\t"
			       << row.strand << "\t" << row.para << "\t"
			       << row.identity_round << "\t" << row.start << "\t"
			       << row.cutlength << "\t" << row.prealign_threshold << "\t"
			       << row.gpu_score << "\t" << row.gpu_query_end << "\t"
			       << row.gpu_ref_end_global << "\t" << (row.selected ? 1 : 0) << "\t"
			       << row.selection_reason << "\t" << (row.cpu_called ? 1 : 0) << "\t"
			       << row.cpu_score << "\t" << row.cpu_query_begin << "\t"
			       << row.cpu_query_end << "\t" << row.cpu_ref_begin_local << "\t"
			       << row.cpu_ref_end_local << "\t" << row.cpu_cigar << "\t"
			       << row.cpu_emit_reason << "\t" << row.converted_row_digest << "\t"
			       << row.final_row_digest << "\t" << row.final_status << "\n";
			++rows;
			selected_rows += row.selected ? 1 : 0;
			cpu_rows += row.cpu_called ? 1 : 0;
			final_rows += row.final_row_digest != "NA" ? 1 : 0;
		}
		output.flush();
		if (!output)
		{
			fail("telemetry_write_failed");
			return false;
		}
		return true;
	}

	bool requested;
	bool active;
	bool failed;
	uint64_t next_batch_id;
	uint64_t rows;
	uint64_t selected_rows;
	uint64_t cpu_rows;
	uint64_t final_rows;
	std::string path;
	std::string failure_reason;
	std::ofstream output;
};

static inline void fasim_print_canonical_hybrid_v2_telemetry_stats(
	const FasimCanonicalHybridV2TelemetryExporter &exporter)
{
	std::cerr << "benchmark.fasim_canonical_hybrid_v2_requested="
	          << (exporter.requested ? 1 : 0) << "\n";
	std::cerr << "benchmark.fasim_canonical_hybrid_v2_active="
	          << (exporter.active && !exporter.failed ? 1 : 0) << "\n";
	std::cerr << "benchmark.fasim_canonical_hybrid_v2_telemetry_rows="
	          << exporter.rows << "\n";
	std::cerr << "benchmark.fasim_canonical_hybrid_v2_selected_rows="
	          << exporter.selected_rows << "\n";
	std::cerr << "benchmark.fasim_canonical_hybrid_v2_cpu_traceback_rows="
	          << exporter.cpu_rows << "\n";
	std::cerr << "benchmark.fasim_canonical_hybrid_v2_final_row_mappings="
	          << exporter.final_rows << "\n";
	std::cerr << "benchmark.fasim_canonical_hybrid_v2_telemetry_path="
	          << exporter.path << "\n";
	std::cerr << "benchmark.fasim_canonical_hybrid_v2_failure_reason="
	          << exporter.failure_reason << "\n";
}

